package fleetflow.engine.suffix;
import java.util.Arrays;
public final class SuffixArray { private SuffixArray(){} public static int[] build(String text){Integer[] order=new Integer[text.length()];for(int i=0;i<order.length;i++)order[i]=i;Arrays.sort(order,(a,b)->text.substring(a).compareTo(text.substring(b)));int[] result=new int[order.length];for(int i=0;i<order.length;i++)result[i]=order[i];return result;} public static boolean contains(String text,String pattern){int[] sa=build(text);int lo=0,hi=sa.length-1;while(lo<=hi){int mid=(lo+hi)>>>1;String suffix=text.substring(sa[mid]);int cmp=suffix.length()<pattern.length()?suffix.compareTo(pattern):suffix.substring(0,pattern.length()).compareTo(pattern);if(cmp==0)return true;if(cmp<0)lo=mid+1;else hi=mid-1;}return pattern.isEmpty();} }
